%% ===========================================================================
%  <算法名称> 参数配置
%  版本: 1.0
%  说明: 统一管理所有仿真参数
% ============================================================================

%% 系统参数
cfg.fs       = 1e6;       % 采样率 (Hz)
cfg.fclk     = 100e6;     % 时钟频率 (Hz)
cfg.N        = 1024;      % 处理点数

%% 算法参数
cfg.param1   = 64;        % 参数1说明
cfg.param2   = 16;        % 参数2说明
cfg.mode     = 'normal';  % 运行模式: 'normal' | 'test'

%% 量化参数 (阶段3后填入)
cfg.quant.Wi = 2;         % 整数位宽
cfg.quant.Wf = 14;        % 小数位宽
cfg.quant.Wt = 16;        % 总位宽

%% 仿真控制
cfg.plot_en      = false;  % 是否绘图
cfg.verbose      = false;  % 是否打印详细信息
cfg.save_vectors = true;   % 是否导出测试向量
